package app.kinnect.audit;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.media.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class StorePackagesAudit extends Instrumentation {
 volatile Activity resumed;int checks;JSONObject fixture;Object api;String theme;
 public void onCreate(Bundle b){super.onCreate(b);start();}public void callActivityOnResume(Activity a){super.callActivityOnResume(a);resumed=a;}
 void check(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}Object call(Object o,String n,Class[] t,Object...v)throws Exception{Method m=o.getClass().getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o,v);}
 Activity open(String name)throws Exception{resumed=null;getTargetContext().startActivity(new Intent().setClassName("app.kinnect.live","app.kinnect.live."+name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int n=0;n<100;n++){if(resumed!=null&&resumed.getClass().getName().endsWith(name)){call(api,"configure",new Class[]{String.class},"https://127.0.0.1:9");return resumed;}Thread.sleep(100);}throw new AssertionError("No Activity "+name);}
 View find(View v,String s){if(s.equals(v.getTag())||s.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&s.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View result=find(((ViewGroup)v).getChildAt(i),s);if(result!=null)return result;}return null;}
 void click(View v){check(v!=null,"Missing button");View item=v;while(!item.isClickable()&&item.getParent() instanceof View)item=(View)item.getParent();final View target=item;runOnMainSync(()->target.performClick());}
 void shot(Activity a,String name)throws Exception{String wanted=name.contains("wallet")?"Xu tặng":name.contains("gifts")?"Quà Live":null;if(wanted!=null)for(int n=0;n<40;n++){android.view.accessibility.AccessibilityNodeInfo window=getUiAutomation().getRootInActiveWindow();if(window!=null&&!window.findAccessibilityNodeInfosByText(wanted).isEmpty())break;Thread.sleep(100);}Thread.sleep(1400);try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}}
 void bounds(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.getLayout()!=null&&t.getWidth()>0&&t.getHeight()>0){check(t.getLayout().getHeight()<=t.getHeight()-t.getPaddingTop()-t.getPaddingBottom()+2,"Text height clipped: "+t.getText());for(int n=0;n<t.getLineCount();n++)check(t.getLayout().getLineWidth(n)<=t.getWidth()-t.getPaddingLeft()-t.getPaddingRight()+2,"Text width clipped: "+t.getText());}}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)bounds(((ViewGroup)v).getChildAt(i));}
 public void onStart(){Bundle out=new Bundle();Activity active=null;try{ClassLoader cl=getTargetContext().getClassLoader();api=cl.loadClass("app.kinnect.live.NativeApi").getField("shared").get(null);try(InputStream in=getContext().getAssets().open("store32-fixture.json")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);fixture=new JSONObject(bytes.toString("UTF-8"));}theme=getTargetContext().getSharedPreferences("kinnect_settings",0).getString("theme","auto");
 for(String variant:new String[]{"light","dark"}){getTargetContext().getSharedPreferences("kinnect_settings",0).edit().putString("theme",variant).commit();active=open("StoreActivity");final Activity store=active;runOnMainSync(()->{try{set(store,"catalog",fixture.getJSONObject("store"));call(store,"draw",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(250);for(String tab:new String[]{"style","studio","live","gifts","member","owned"}){runOnMainSync(()->{try{call(store,"selectTab",new Class[]{String.class},tab);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(200);bounds(store.getWindow().getDecorView());if(tab.equals("studio")){for(String id:new String[]{"studio_7","studio_30","studio_365"})check(find(store.getWindow().getDecorView(),"store:price:"+id)!=null,"Missing Studio price "+id);check(find(store.getWindow().getDecorView(),"Kích hoạt")!=null,"Paid Studio activation missing");check(find(store.getWindow().getDecorView(),"Đang miễn phí trải nghiệm")==null,"Obsolete free banner");}if(tab.equals("live")){check(find(store.getWindow().getDecorView(),"Miễn phí")!=null,"Chat free label missing");check(find(store.getWindow().getDecorView(),"store:price:live_game_30")!=null,"Game price missing");}shot(store,"store32-"+tab+"-"+variant+".png");}runOnMainSync(()->store.finish());}
 active=open("WalletActivity");final Activity wallet=active;runOnMainSync(()->{try{call(wallet,"draw",new Class[]{JSONObject.class},fixture.getJSONObject("wallet"));}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(200);check(((TextView)find(wallet.getWindow().getDecorView(),"wallet:coins")).getText().toString().contains("2.000"),"Gifted balance mixed");check(((TextView)find(wallet.getWindow().getDecorView(),"wallet:purchased")).getText().toString().contains("250"),"Purchased balance missing");check(((TextView)find(wallet.getWindow().getDecorView(),"wallet:earnings")).getText().toString().contains("32.500"),"Withdrawable total wrong");bounds(wallet.getWindow().getDecorView());shot(wallet,"store32-wallet.png");runOnMainSync(()->wallet.finish());
 active=open("CoinGrantActivity");final Activity grants=active;runOnMainSync(()->{try{call(grants,"renderPeople",new Class[]{JSONArray.class},fixture.getJSONArray("people"));}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(200);View one=find(grants.getWindow().getDecorView(),"grants:user:one");check(one!=null,"Selection missing");click(one);check(((TextView)find(grants.getWindow().getDecorView(),"grants:count")).getText().toString().contains("1"),"Selected count wrong");bounds(grants.getWindow().getDecorView());shot(grants,"store32-grants.png");click(find(grants.getWindow().getDecorView(),"grants:all"));check(((View)get(grants,"people")).getVisibility()==View.GONE,"All mode duplicates selection");check(((Button)find(grants.getWindow().getDecorView(),"grants:review")).isEnabled(),"All review disabled");runOnMainSync(()->{try{set(grants,"prepared",new JSONObject().put("count",123).put("coins",2000).put("totalCoins",246000));call(grants,"confirmation",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(200);check(!getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText("246.000").isEmpty(),"Grant total missing");shot(grants,"store32-grant-confirm.png");getUiAutomation().executeShellCommand("input keyevent 4").close();out.putString("result","PASS "+checks+": six storefront tabs, Studio3 paid prices/no free banner, Chat free/Game490, grant selection/all mode/confirmation;gifted/purchased/withdrawable wallet;320dp/font130/light+dark; no public mutations");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}finally{final Activity last=active;runOnMainSync(()->{if(last!=null)last.finish();});getTargetContext().getSharedPreferences("kinnect_settings",0).edit().putString("theme",theme==null?"auto":theme).commit();}}
}
